import{_ as d,C as s,o as t,c as n,a2 as o,b as c,w as a,a as i,E as l,a3 as h}from"./chunks/framework.yZB1U4Nl.js";const y=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"concepts.md","filePath":"concepts.md"}'),u={name:"concepts.md"};function p(m,e,g,f,k,w){const r=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><p>One model underlies everything: a run is a journal of events, a workflow is a pure function that folds those events into state and asks for effects, and the host executes the effects.</p><h2 id="vocabulary" tabindex="-1">Vocabulary <a class="header-anchor" href="#vocabulary" aria-label="Permalink to &quot;Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Run</strong></td><td>One execution of a workflow. Has a <code>run_id</code>, a status, an ordered journal of events (<code>seq</code> 1, 2, 3…), and exactly one state checkpoint.</td></tr><tr><td><strong>Workflow</strong></td><td>A named reducer built with <code>defineWorkflow(name, { init, on })</code>. <code>init(input)</code> builds the first state; <code>on.&lt;event&gt;(state, event)</code> returns <code>[state, commands]</code>.</td></tr><tr><td><strong>Event</strong></td><td>Something that happened to a run: <code>started</code>, <code>task_done</code>, <code>signal</code>, <code>timer</code>, <code>child_done</code>. Every event carries <code>ts_ms</code>, 32 hex chars of journaled <code>random</code>, and the run&#39;s banked <code>usage_total</code>.</td></tr><tr><td><strong>Command</strong></td><td>What a reducer asks for: <code>task</code>, <code>timer</code>, <code>spawn</code>, <code>await_signal</code>, <code>emit</code>, <code>complete</code>, <code>continue_as_new</code>. Built with <code>cmd.*</code>; plain JSON.</td></tr><tr><td><strong>Step</strong></td><td>One unit of scheduled work inside a run, opened by a command: a task, a timer, a signal wait, a child run, or a marker. Identified by a <code>step_id</code> (<code>task#3</code>, or one you choose).</td></tr><tr><td><strong>Activity</strong></td><td>The declaration of a piece of non-deterministic work: a name, Zod input and output schemas, a retry policy, a queue. Content-hashed: <code>name@hash</code> is its <code>schema_ref</code>.</td></tr><tr><td><strong>Task</strong></td><td>A row in the journal that a worker executes to perform an activity. Has a <code>task_id</code> (<code>run:step</code>), an <code>attempt</code>, an <code>idempotency_key</code> (<code>run:step:attempt</code>), a lease and a retry policy.</td></tr><tr><td><strong>Signal</strong></td><td>A durable message into a run: a human reply, a webhook, a budget top-up. Declared with <code>signal(name, schema)</code>; delivered by <code>POST /v1/runs/{id}/signals/{name}</code>. Buffered if nothing is waiting yet.</td></tr><tr><td><strong>Timer</strong></td><td>A durable deadline. <code>cmd.timer({ ms })</code> parks the run; the host fires it as a <code>timer</code> event, exactly once.</td></tr><tr><td><strong>Child run</strong></td><td>A run started by <code>cmd.spawn</code>. When it ends, its parent receives <code>child_done</code> with the child&#39;s status and output.</td></tr><tr><td><strong>Journal</strong></td><td>Your Postgres database or a SQLite file. Holds runs, events, the state checkpoint, tasks, timers, signals. It is also the queue: there is no broker.</td></tr><tr><td><strong>Blob store</strong></td><td>A directory (<code>file://</code>) or a bucket (<code>gcs://</code>) for payloads over 256 KiB. The journal stores a <code>blob://sha256/&lt;hex&gt;</code> reference instead.</td></tr><tr><td><strong>Kernel</strong></td><td>The Rust state machine, compiled to wasm and loaded by the host. Validates events, calls your reducer, validates commands, and produces the write-set the journal applies. No I/O.</td></tr><tr><td><strong>Host</strong></td><td>The Node process around the kernel: opens the journal, serves HTTP, runs the dispatcher, runs in-process workers. <code>@oona/vlo/host</code>.</td></tr><tr><td><strong>Role</strong></td><td>What one host process does: <code>orchestrator</code>, <code>api</code>, <code>worker:&lt;queue&gt;</code>. A process may hold any subset.</td></tr><tr><td><strong>Worker</strong></td><td>Activity implementations: <code>defineWorker({ &quot;name&quot;: handler })</code> plus the queues it serves. In-process, pushed to over HTTP, or polling.</td></tr><tr><td><strong>Profile</strong></td><td>One named deployment configuration in <code>vlo.config.ts</code>: journal, blob, roles, queues, auth, dispatcher mode, deploy target.</td></tr></tbody></table><h2 id="the-loop" tabindex="-1">The loop <a class="header-anchor" href="#the-loop" aria-label="Permalink to &quot;The loop&quot;">​</a></h2>',5)),(t(),c(h,null,{default:a(()=>[l(r,{id:"mermaid-162",class:"mermaid",graph:"sequenceDiagram%0A%20%20participant%20C%20as%20Client%0A%20%20participant%20H%20as%20Host%20(api%20%2B%20orchestrator)%0A%20%20participant%20K%20as%20Kernel%20(wasm)%0A%20%20participant%20J%20as%20Journal%0A%20%20participant%20W%20as%20Worker%0A%20%20C-%3E%3EH%3A%20POST%20%2Fv1%2Fruns%0A%20%20H-%3E%3EJ%3A%20run%20row%2C%20status%20created%0A%20%20H-%3E%3EK%3A%20started%20event%20%2B%20init%20input%0A%20%20K-%3E%3EK%3A%20reducer(state%2C%20event)%20%E2%86%92%20%5Bstate%2C%20commands%5D%0A%20%20K--%3E%3EH%3A%20write-set%20(events%2C%20tasks%2C%20timers%E2%80%A6)%0A%20%20H-%3E%3EJ%3A%20one%20transaction%3A%20event%2C%20checkpoint%2C%20task%20row%0A%20%20H-%3E%3EW%3A%20push%20task%20(HTTP%20or%20in-process)%0A%20%20W--%3E%3EH%3A%20202%20accepted%0A%20%20W-%3E%3EH%3A%20POST%20%2Fv1%2Ftasks%2F%7Bid%7D%2Fcomplete%0A%20%20H-%3E%3EK%3A%20task_done%20event%0A%20%20K--%3E%3EH%3A%20next%20write-set%0A%20%20H-%3E%3EJ%3A%20commit%0A%20%20H--%3E%3EC%3A%20SSE%20%2F%20GET%20%2Fv1%2Fruns%2F%7Bid%7D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>Every event goes through the same path: lock the run, load the checkpoint, fold, commit. The dispatcher (the <code>orchestrator</code> role) reads committed rows on each tick and does the effects: starts <code>created</code> runs, pushes <code>scheduled</code> tasks, fires due timers, reaps lapsed leases and timeouts, and tells parents about closed children. A crash between &quot;committed&quot; and &quot;pushed&quot; is recovered by the next tick, on any process holding the role.</p><h2 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h2><p>Run status (<code>RunStatus</code>): <code>created</code> → <code>running</code> → <code>awaiting_signal</code> ⇄ <code>running</code> → <code>completed</code> | <code>failed</code> | <code>cancelled</code> | <code>continued</code>. The last four are terminal; a run in a terminal status accepts no further events.</p><p>Step status (<code>Status</code>): <code>scheduled</code>, <code>running</code>, <code>succeeded</code>, <code>failed</code>, <code>retrying</code>, <code>cancelled</code>, <code>awaiting_signal</code>.</p><p>Failure cause (<code>Cause</code>): <code>timeout</code>, <code>heartbeat_lost</code>, <code>app_error</code>, <code>user_cancel</code>, <code>schema_violation</code>, <code>nondeterminism_detected</code>. The last three are never retried.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Owns</th></tr></thead><tbody><tr><td><code>orchestrator</code></td><td>The dispatcher: the only thing that turns rows into effects. Also the <code>POST /v1/timers/tick</code> route.</td></tr><tr><td><code>api</code></td><td>The control plane: <code>/v1/runs…</code>, <code>/v1/tasks/{id}/complete|fail|heartbeat</code>, <code>/v1/tasks/poll</code>.</td></tr><tr><td><code>worker:&lt;queue&gt;</code></td><td>Runs activities on <code>&lt;queue&gt;</code>: in-process when the orchestrator is the same process, or via <code>POST /v1/tasks/push</code> from a remote one.</td></tr></tbody></table><p>With no <code>roles</code> configured a process holds <code>orchestrator</code>, <code>api</code> and <code>worker:&lt;q&gt;</code> for every queue its workers declare. Splitting is a profile change; see <a href="./deployment">deployment.md</a>.</p><h2 id="two-ways-a-task-reaches-a-worker" tabindex="-1">Two ways a task reaches a worker <a class="header-anchor" href="#two-ways-a-task-reaches-a-worker" aria-label="Permalink to &quot;Two ways a task reaches a worker&quot;">​</a></h2><ul><li><strong>Push</strong> (default). The dispatcher POSTs the task to the queue&#39;s URL with an HMAC signature; the worker answers <code>202</code> and reports later on <code>complete_url</code>. A queue with no URL is served only by a worker in the same process.</li><li><strong>Pull</strong>. <code>mode: &quot;pull&quot;</code> queues are never pushed. Workers long-poll <code>POST /v1/tasks/poll</code> and get the same task shape.</li></ul><p>Both share one accept path: the task is marked <code>running</code> with a lease in the same transaction as the hand-off, so the reaper and crash recovery see no difference.</p><h2 id="determinism-briefly" tabindex="-1">Determinism, briefly <a class="header-anchor" href="#determinism-briefly" aria-label="Permalink to &quot;Determinism, briefly&quot;">​</a></h2><p>A reducer must be pure: no clock, no randomness, no I/O. Every non-deterministic input (<code>ts_ms</code>, <code>random</code>, task outputs, signal payloads) arrives on the event. The host hashes the checkpoint on every load and rebuilds it from seq 0 when it is missing; a rebuilt state that disagrees with the journal fails the run with <code>nondeterminism_detected</code>. Details in <a href="./workflows#determinism">workflows.md</a>.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="./why-vlo">why-vlo.md</a> — what the reducer buys you, and what it costs.</li><li><a href="./reliability">reliability.md</a> — what Vlo guarantees, in one place.</li><li><a href="./journal">journal.md</a> — tables, dialects, the checkpoint.</li><li><a href="./kernel-protocol">kernel-protocol.md</a> — the host ⇄ kernel calls.</li><li><a href="./architecture">architecture.md</a> — how the pieces are laid out.</li></ul>',15))])}const v=d(u,[["render",p]]);export{y as __pageData,v as default};
